const body = items[0].json.body || items[0].json || {};
const entry = (body.entry || [])[0] || {};
const change = (entry.changes || [])[0] || {};
const value = change.value || {};
const messages = value.messages || [];
const msg = messages[0] || {};
const text = (msg.text && msg.text.body) || (msg.button && msg.button.text) || (msg.interactive && msg.interactive.button_reply && msg.interactive.button_reply.title) || '';
const buttonPayload = (msg.button && msg.button.payload) || (msg.interactive && msg.interactive.button_reply && msg.interactive.button_reply.id) || '';
const phoneNumberId = (value.metadata && value.metadata.phone_number_id) || '';

if (!phoneNumberId || !text.trim()) {
  items[0].json = { _skip: true, _phone_number_id: phoneNumberId, _message_text: '' };
  return items;
}

items[0].json = {
  _skip: false,
  _phone_number_id: phoneNumberId,
  _from: msg.from || '',
  _message_text: text.trim(),
  _message_id: msg.id || '',
  _timestamp: msg.timestamp || '',
  _waba_id: entry.id || '',
  _button_payload: buttonPayload,
  _raw: body
};
return items;

const prev = $node['Parsear mensaje'].json;
const resp = items[0].json;

let rows = [];
if (Array.isArray(resp)) {
  rows = resp;
} else if (resp && Array.isArray(resp.body)) {
  rows = resp.body;
} else if (resp && resp.phone_number_id) {
  rows = [resp];
} else if (resp && typeof resp === 'object' && Object.keys(resp).length > 0) {
  rows = [resp];
}

if (!rows || rows.length === 0) {
  items[0].json = { _routed: false, _reason: 'no_connection', ...prev };
  return items;
}

const conn = rows[0];

// Filtrar eco (el negocio se envía a sí mismo)
const bizNumber = (conn.display_phone_number || '').replace(/\D/g, '');
const fromNumber = (prev._from || '').replace(/\D/g, '');
if (bizNumber && fromNumber && bizNumber === fromNumber) {
  items[0].json = { _routed: false, _reason: 'echo', ...prev };
  return items;
}

items[0].json = {
  _routed: true,
  _user_id: conn.user_id,
  _instance_id: conn.instance_id,
  _access_token: conn.access_token,
  _phone_number_id: prev._phone_number_id,
  _from: prev._from,
  _message_text: prev._message_text,
  _message_id: prev._message_id,
  _waba_id: prev._waba_id,
  _display_phone_number: conn.display_phone_number || null,
  _button_payload: prev._button_payload || ''
};
return items;

const msg = $node['Enriquecer + filtrar eco'].json;
const p = items[0].json;

const systemPrompt = p.system_prompt || p.bot_prompt || p.personality || 'Eres un asistente conciso y amable en español que ayuda a los clientes de una tienda online. Responde brevemente.';

items[0].json = {
  ...msg,
  _system_prompt: systemPrompt,
  _ai_name: p.ai_name || null,
  _ai_tone: p.ai_tone || null,
  _biz_name: p.biz_name || null,
  _reply_public: p.reply_public || null
};
return items;

