const saldo = $('Get Profile').first().json;
const planType = (saldo.plan_type || 'free').toLowerCase();
const puedeAgendar = planType === 'full';

// Los servicios vienen del nodo HTTP Request anterior
const inputItems = $('Traer Servicios').all();
const servicios = inputItems.map(item => item.json);

let serviciosTexto = '';

if (servicios.length > 0) {
  const lineas = servicios.map(s => {
    let linea = `- ${s.name}`;
    if (s.price) linea += `: $${Number(s.price).toLocaleString('es-CL')}`;
    if (s.duration_minutes && s.duration_minutes > 0) linea += ` (${s.duration_minutes} min)`;
    if (s.description) linea += ` — ${s.description}`;
    return linea;
  });

  serviciosTexto = '\n\nServicios disponibles del negocio:\n' + lineas.join('\n');

  if (puedeAgendar) {
    serviciosTexto += '\n\nINSTRUCCIÓN DE AGENDAMIENTO: Este negocio tiene agendamiento activo. Si el cliente quiere agendar una cita para cualquiera de estos servicios, usa la herramienta "Call Tool - Agendador" para buscar disponibilidad y crear la cita.';
  } else {
    serviciosTexto += '\n\nNOTA: Este negocio NO tiene agendamiento automático. Si el cliente quiere agendar, indícale que contacte directamente al negocio para coordinar una hora.';
  }
}

return [{
  json: {
    ...($input.first().json),
    servicios_texto: serviciosTexto,
    plan_type: planType,
    puede_agendar: puedeAgendar,
    cantidad_servicios: servicios.length
  }
}];

const citas = $input.all().map(item => item.json);
const serviciosData = $('Formatear Servicios').first().json;

let citasContexto = '';

if (citas && citas.length > 0 && citas[0].id) {
  const lineas = citas.map(c => {
    try {
      const fecha = new Date(c.starts_at);
      const dia = fecha.toLocaleDateString('es-CL', { weekday: 'long', day: 'numeric', month: 'short', timeZone: 'America/Santiago' });
      const hora = fecha.toLocaleTimeString('es-CL', { hour: '2-digit', minute: '2-digit', timeZone: 'America/Santiago' });
      const servicio = (c.services && c.services.name) ? c.services.name : 'Servicio';
      const profesional = (c.staff_members && c.staff_members.name) ? c.staff_members.name : '';
      return '- ' + servicio + (profesional ? ' con ' + profesional : '') + ' | ' + dia + ' ' + hora + ' | Estado: ' + c.status;
    } catch (e) {
      return '- Cita pendiente';
    }
  });
  citasContexto = '\n\n[CITAS PENDIENTES DEL CLIENTE]\n' + lineas.join('\n') + '\nSi el cliente dice "si", "confirmo", "gracias" o similar sin contexto claro, probablemente responde a una confirmacion de cita enviada por WhatsApp. Responde confirmando los detalles de su cita.';
}

return [{
  json: {
    ...serviciosData,
    citas_contexto: citasContexto
  }
}];

