const payload = $node['Enriquecer + filtrar eco'].json._button_payload || '';
const match = payload.match(/^(CONFIRM|CANCEL)_APT_(.+)$/);
if (!match) {
  items[0].json = { _apt_error: 'Invalid payload' };
  return items;
}
const action = match[1];
const appointmentId = match[2];
const newStatus = action === 'CONFIRM' ? 'confirmed' : 'cancelled';
const enriched = $node['Enriquecer + filtrar eco'].json;

items[0].json = {
  _action: action,
  _appointment_id: appointmentId,
  _new_status: newStatus,
  _user_id: enriched._user_id,
  _access_token: enriched._access_token,
  _phone_number_id: enriched._phone_number_id,
  _from: enriched._from,
  _message_text: enriched._message_text
};
return items;

