const rows = items.map(i => i.json);
let allMsgs = [];
if (Array.isArray(rows) && rows.length > 0) {
  if (Array.isArray(rows[0])) {
    allMsgs = rows[0];
  } else if (rows[0].body) {
    allMsgs = rows;
  }
}

allMsgs.sort((a, b) => new Date(a.created_at) - new Date(b.created_at));

const lines = allMsgs.map(m => {
  const role = m.direction === 'inbound' ? '[Cliente]'
    : (m.sender_type === 'system' ? '[Sistema]' : '[Bot]');
  return role + ': ' + (m.body || '').substring(0, 300);
});

const enriched = $node['Enriquecer + filtrar eco'].json;
items[0].json = {
  ...enriched,
  _chat_history: lines.length > 0
    ? '[HISTORIAL DE CONVERSACIÓN RECIENTE CON ESTE CLIENTE]\n' + lines.join('\n')
    : ''
};
return items;
